arguments.command:
python3 - <<'EOF'
import json, collections
rows = [json.loads(l) for l in open('metrics.jsonl')]
ro = [r for r in rows if r['step_key']=='rollout/step']
by = collections.defaultdict(dict)
for r in ro: by[r['step']].update(r['data'])
for s in sorted(by):
    d = by[s]
    line = f"roll {s:3d} rew={d.get('rollout/raw_reward_mean', float('nan')):.4f}"
    for k, tag in [('rollout/rewards','R'),('rollout/advantages','A'),('rollout/values','V'),('rollout/returns','Ret'),
                   ('rollout/entropy','H'),('rollout/log_probs','lp'),('rollout/rollout_log_probs','rlp'),('rollout/truncated','tr'),('rollout/response_lengths','len')]:
        if k in d:
            v=d[k]
            line += f" {tag}={v:.3f}" if isinstance(v,float) else f" {tag}={v}"
    if 'grpo_metrics/no_grad' in d:
